#include "shapes.h"

int rectArea(int length, int width) {
    return length * width;
}

int rectPerimeter(int length, int width) {
    return 2 * (length + width);
}

#include <stdio.h>
#include "shapes.h"

int main(void) {
    int l = 8, w = 5;
    printf("Area: %d\n", rectArea(l, w));
    printf("Perimeter: %d\n", rectPerimeter(l, w));
